SELECT DISTINCT category_id FROM products ORDER BY category_id;
SELECT DISTINCT kind_id FROM products ORDER BY kind_id;
SELECT COUNT(DISTINCT p.sku) AS cnt
FROM products p
JOIN inventory i ON i.sku = p.sku
JOIN stores s ON s.store_id = i.store_id
WHERE (p.category_id = 'work_jackets' OR p.kind_id = 'work_jackets')
  AND i.available_today > 0
  AND s.city = 'Linz'
  AND (s.is_open = 1 OR s.status = 'open');
